import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

const navLinks = [
  { label: 'Home', href: '/' },
  { label: 'Services', href: '/services' },
  { label: 'About', href: '/about' },
  { label: 'Contact', href: '/contact' },
];

export default function Header() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const location = useLocation();

  return (
    <header className="sticky top-0 z-50 bg-white/95 backdrop-blur-sm border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-20 md:h-24">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Sparkle Clean logo"
              className="h-10 md:h-12 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                to={link.href}
                className={cn(
                  'text-sm font-medium transition-colors duration-200 hover:text-primary',
                  location.pathname === link.href
                    ? 'text-primary'
                    : 'text-gray-600'
                )}
              >
                {link.label}
              </Link>
            ))}
          </nav>

          {/* CTA + Mobile Toggle */}
          <div className="flex items-center gap-3">
            <Button asChild className="hidden md:inline-flex bg-primary hover:bg-primary/90 text-primary-foreground rounded-full px-6 font-semibold transition-all duration-200">
              <Link to="/contact">Get a Free Quote</Link>
            </Button>
            <button
              className="md:hidden p-2 rounded-lg text-gray-600 hover:text-primary hover:bg-muted transition-colors"
              onClick={() => setMobileOpen(!mobileOpen)}
              aria-label="Toggle menu"
            >
              {mobileOpen ? <X size={22} /> : <Menu size={22} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {mobileOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 px-4 py-4 space-y-1">
          {navLinks.map((link) => (
            <Link
              key={link.href}
              to={link.href}
              onClick={() => setMobileOpen(false)}
              className={cn(
                'block px-4 py-3 rounded-lg text-sm font-medium transition-colors',
                location.pathname === link.href
                  ? 'bg-muted text-primary'
                  : 'text-gray-600 hover:bg-muted hover:text-primary'
              )}
            >
              {link.label}
            </Link>
          ))}
          <div className="pt-2">
            <Button asChild className="w-full bg-primary hover:bg-primary/90 text-primary-foreground rounded-full font-semibold">
              <Link to="/contact" onClick={() => setMobileOpen(false)}>Get a Free Quote</Link>
            </Button>
          </div>
        </div>
      )}
    </header>
  );
}

import { Link } from 'react-router-dom';
import { motion } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { Button } from '@/components/ui/button';
import { ShieldCheck, Leaf, ThumbsUp, Star, ArrowRight, CheckCircle } from 'lucide-react';

// ─── Animation Variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.35, ease: 'easeOut' as const, delay },
  }),
};

const fadeIn = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { duration: 0.35, ease: 'easeOut' as const },
  },
};

// ─── Trust Badges ─────────────────────────────────────────────────────────────

const trustBadges = [
  { icon: ShieldCheck, label: 'Insured & Bonded' },
  { icon: Leaf, label: 'Eco-Friendly Products' },
  { icon: ThumbsUp, label: 'Satisfaction Guaranteed' },
  { icon: Star, label: '5-Star Rated' },
];

// ─── Services ─────────────────────────────────────────────────────────────────

const services = [
  {
    title: 'Regular Cleaning',
    description:
      'Keep your home consistently fresh with our scheduled cleaning visits. We handle dusting, vacuuming, mopping, kitchen surfaces, and bathrooms — so you never have to think about it.',
    bullets: ['Weekly or bi-weekly scheduling', 'All rooms covered', 'Consistent, trusted team'],
    image: '/airo-assets/images/services/regular-cleaning',
    imageAlt: 'Professional cleaner tidying a bright living room',
  },
  {
    title: 'Deep Clean',
    description:
      'A thorough top-to-bottom clean that reaches every corner. Perfect for spring cleaning, post-renovation, or when your home needs a serious reset.',
    bullets: ['Inside appliances & cabinets', 'Grout, tile & baseboards', 'Ideal for seasonal resets'],
    image: '/airo-assets/images/services/deep-clean',
    imageAlt: 'Cleaner scrubbing a sparkling bathroom',
  },
  {
    title: 'Move-In / Move-Out',
    description:
      'Starting fresh or leaving on a good note. Our move cleaning ensures every surface is spotless — so you get your deposit back or welcome new owners in style.',
    bullets: ['Full property coverage', 'Deposit-ready results', 'Flexible scheduling'],
    image: '/airo-assets/images/services/move-in-out',
    imageAlt: 'Clean empty apartment ready for move-in',
  },
];

// ─── Testimonials ─────────────────────────────────────────────────────────────

const testimonials = [
  {
    name: 'Sarah M.',
    location: 'Homeowner',
    quote:
      "Sparkle Clean has been a game-changer for our family. The team is thorough, reliable, and my house has never looked better. I can't imagine going back to doing it myself.",
    stars: 5,
  },
  {
    name: 'James T.',
    location: 'Condo Owner',
    quote:
      'I hired them for a deep clean before listing my condo and the results were incredible. My realtor actually commented on how spotless everything was. Highly recommend.',
    stars: 5,
  },
  {
    name: 'Priya K.',
    location: 'Regular Client',
    quote:
      "Friendly, professional, and they always go above and beyond. I've been a regular client for over a year and the quality never slips. Worth every penny.",
    stars: 5,
  },
];

// ─── Component ────────────────────────────────────────────────────────────────

export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Sparkle Clean — Professional House Cleaning Services</title>
        <meta
          name="description"
          content="Sparkle Clean offers professional residential house cleaning services. Regular cleaning, deep cleans, and move-in/move-out packages. Get a free quote today."
        />
      </Helmet>

      {/* ── Hero ─────────────────────────────────────────────────────────── */}
      <section className="relative min-h-[90vh] flex items-center overflow-hidden">
        {/* Background image */}
        <div className="absolute inset-0">
          <img
            src="/airo-assets/images/pages/home/hero"
            alt="Bright, clean modern living room"
            className="w-full h-full object-cover"
            fetchPriority="high"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-gray-900/70 via-gray-900/50 to-gray-900/20" />
        </div>

        {/* Content */}
        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
          <div className="max-w-2xl">
            <motion.h1
              className="text-5xl sm:text-6xl lg:text-7xl font-bold text-white leading-tight tracking-tight"
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0}
            >
              Your Home,{' '}
              <span className="text-primary">Spotless.</span>
            </motion.h1>

            <motion.p
              className="mt-6 text-lg sm:text-xl text-gray-200 leading-relaxed max-w-lg"
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.12}
            >
              Professional house cleaning you can count on. We bring the sparkle — you enjoy the results.
            </motion.p>

            <motion.div
              className="mt-10 flex flex-col sm:flex-row gap-4"
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.24}
            >
              <Button
                asChild
                size="lg"
                className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-full px-8 py-6 text-base font-semibold shadow-lg transition-all duration-200 hover:shadow-xl hover:-translate-y-0.5"
              >
                <Link to="/contact">Get a Free Quote</Link>
              </Button>
              <Button
                asChild
                variant="outline"
                size="lg"
                className="bg-white/10 border-white/40 text-white hover:bg-white/20 rounded-full px-8 py-6 text-base font-semibold backdrop-blur-sm transition-all duration-200"
              >
                <Link to="/services">
                  See Our Services <ArrowRight size={16} className="ml-2" />
                </Link>
              </Button>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ── Trust Badges ─────────────────────────────────────────────────── */}
      <section className="bg-muted py-8 border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-wrap items-center justify-center gap-6 sm:gap-10">
            {trustBadges.map(({ icon: Icon, label }) => (
              <div key={label} className="flex items-center gap-2.5 text-gray-700">
                <Icon size={18} className="text-primary shrink-0" />
                <span className="text-sm font-semibold whitespace-nowrap">{label}</span>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── Services ─────────────────────────────────────────────────────── */}
      <section className="py-24 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            className="text-center mb-16"
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            <p className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">What We Offer</p>
            <h2 className="text-4xl sm:text-5xl font-bold text-gray-900">Cleaning Services Built for Your Life</h2>
          </motion.div>

          <div className="space-y-20">
            {services.map((service, i) => {
              const isEven = i % 2 === 0;
              return (
                <motion.div
                  key={service.title}
                  className={`grid grid-cols-1 lg:grid-cols-2 gap-10 lg:gap-16 items-center ${
                    isEven ? '' : 'lg:[&>*:first-child]:order-2'
                  }`}
                  variants={fadeUp}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                >
                  {/* Image */}
                  <div className="relative rounded-2xl overflow-hidden shadow-xl aspect-[4/3]">
                    <img
                      src={service.image}
                      alt={service.imageAlt}
                      className="w-full h-full object-cover transition-transform duration-500 hover:scale-105"
                    />
                  </div>

                  {/* Text */}
                  <div className="space-y-5">
                    <h3 className="text-3xl font-bold text-gray-900">{service.title}</h3>
                    <p className="text-gray-600 leading-relaxed text-lg">{service.description}</p>
                    <ul className="space-y-2.5">
                      {service.bullets.map((b) => (
                        <li key={b} className="flex items-center gap-3 text-gray-700">
                          <CheckCircle size={17} className="text-primary shrink-0" />
                          <span className="text-sm font-medium">{b}</span>
                        </li>
                      ))}
                    </ul>
                    <Button
                      asChild
                      variant="outline"
                      className="rounded-full border-primary text-primary hover:bg-primary hover:text-primary-foreground transition-all duration-200 mt-2"
                    >
                      <Link to="/contact">Book This Service <ArrowRight size={14} className="ml-2" /></Link>
                    </Button>
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>
      </section>

      {/* ── Testimonials ─────────────────────────────────────────────────── */}
      <section className="py-24 bg-muted">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            className="text-center mb-14"
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            <p className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">Happy Clients</p>
            <h2 className="text-4xl sm:text-5xl font-bold text-gray-900">What Our Customers Say</h2>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {testimonials.map((t, i) => (
              <motion.div
                key={t.name}
                className="bg-white rounded-2xl p-8 shadow-sm hover:shadow-md transition-shadow duration-300 hover:-translate-y-1 transition-transform"
                variants={fadeUp}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={i * 0.1}
              >
                {/* Stars */}
                <div className="flex gap-1 mb-4">
                  {Array.from({ length: t.stars }).map((_, j) => (
                    <Star key={j} size={16} className="fill-yellow-400 text-yellow-400" />
                  ))}
                </div>
                <p className="text-gray-700 leading-relaxed mb-6 italic">"{t.quote}"</p>
                <div>
                  <p className="font-semibold text-gray-900">{t.name}</p>
                  <p className="text-sm text-gray-500">{t.location}</p>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* ── CTA ──────────────────────────────────────────────────────────── */}
      <section className="relative py-32 overflow-hidden">
        {/* Background */}
        <div className="absolute inset-0">
          <img
            src="/airo-assets/images/pages/home/cta-background"
            alt="Spotless clean kitchen"
            className="w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-gray-900/85 via-gray-900/70 to-gray-900/40" />
        </div>

        {/* Content — asymmetric left-aligned */}
        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            className="max-w-xl"
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            <h2 className="text-4xl sm:text-5xl font-bold text-white leading-tight mb-6">
              Ready for a Home That Truly Shines?
            </h2>
            <p className="text-gray-300 text-lg leading-relaxed mb-10">
              Book your first cleaning today and see the Sparkle Clean difference. Free quotes, flexible scheduling, and results you'll love.
            </p>
            <Button
              asChild
              size="lg"
              className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-full px-10 py-6 text-base font-semibold shadow-lg transition-all duration-200 hover:shadow-xl hover:-translate-y-0.5"
            >
              <Link to="/contact">Book Your Cleaning</Link>
            </Button>
          </motion.div>
        </div>
      </section>
    </>
  );
}

