import { useState } from 'react';
import { motion } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Phone, Mail, Clock, MapPin, CheckCircle } from 'lucide-react';

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.35, ease: 'easeOut' as const, delay },
  }),
};

const contactInfo = [
  {
    icon: Phone,
    label: 'Phone',
    value: '(555) 123-4567',
    href: 'tel:5551234567',
  },
  {
    icon: Mail,
    label: 'Email',
    value: 'hello@sparkleclean.com',
    href: 'mailto:hello@sparkleclean.com',
  },
  {
    icon: Clock,
    label: 'Hours',
    value: 'Mon–Sat, 8am–6pm',
    href: null,
  },
  {
    icon: MapPin,
    label: 'Service Area',
    value: 'Greater metro area & surrounding suburbs',
    href: null,
  },
];

export default function ContactPage() {
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setLoading(true);
    // Simulate submission delay
    await new Promise((r) => setTimeout(r, 800));
    setLoading(false);
    setSubmitted(true);
  }

  return (
    <>
      <Helmet>
        <title>Contact Us — Sparkle Clean</title>
        <meta
          name="description"
          content="Get in touch with Sparkle Clean to book a cleaning or request a free quote. Call, email, or fill out our contact form."
        />
      </Helmet>

      {/* Page Header */}
      <section className="bg-muted py-16 border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <motion.div variants={fadeUp} initial="hidden" animate="visible">
            <p className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">Get in Touch</p>
            <h1 className="text-4xl sm:text-5xl font-bold text-gray-900">Request a Free Quote</h1>
            <p className="mt-4 text-lg text-gray-600 max-w-xl mx-auto">
              Ready for a sparkling clean home? Fill out the form below or give us a call — we'll get back to you within a few hours.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Main Content */}
      <section className="py-20 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-14">

            {/* Contact Info */}
            <motion.div
              className="lg:col-span-2 space-y-8"
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.1}
            >
              <div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">We'd love to hear from you</h2>
                <p className="text-gray-600 leading-relaxed">
                  Whether you want to schedule a regular clean, book a deep clean, or just have questions — we're here to help.
                </p>
              </div>

              <div className="space-y-5">
                {contactInfo.map(({ icon: Icon, label, value, href }) => (
                  <div key={label} className="flex items-start gap-4">
                    <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center shrink-0 mt-0.5">
                      <Icon size={17} className="text-primary" />
                    </div>
                    <div>
                      <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-0.5">{label}</p>
                      {href ? (
                        <a href={href} className="text-gray-900 font-medium hover:text-primary transition-colors">
                          {value}
                        </a>
                      ) : (
                        <p className="text-gray-900 font-medium">{value}</p>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              {/* What to expect */}
              <div className="bg-muted rounded-2xl p-6 space-y-3">
                <h3 className="font-bold text-gray-900">What happens next?</h3>
                {[
                  'We'll review your request and reach out within a few hours',
                  'We'll confirm your service, date, and pricing',
                  'Our team arrives on time, ready to make your home shine',
                ].map((step, i) => (
                  <div key={i} className="flex items-start gap-3">
                    <CheckCircle size={16} className="text-primary shrink-0 mt-0.5" />
                    <p className="text-sm text-gray-700">{step}</p>
                  </div>
                ))}
              </div>
            </motion.div>

            {/* Contact Form */}
            <motion.div
              className="lg:col-span-3"
              variants={fadeUp}
              initial="hidden"
              animate="visible"
              custom={0.2}
            >
              {submitted ? (
                <div className="flex flex-col items-center justify-center text-center py-20 px-8 bg-muted rounded-2xl h-full">
                  <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mb-5">
                    <CheckCircle size={32} className="text-primary" />
                  </div>
                  <h3 className="text-2xl font-bold text-gray-900 mb-3">Message Sent!</h3>
                  <p className="text-gray-600 max-w-sm">
                    Thanks for reaching out! We'll be in touch within a few hours to confirm your booking details.
                  </p>
                </div>
              ) : (
                <form
                  onSubmit={handleSubmit}
                  className="bg-white border border-gray-100 rounded-2xl shadow-sm p-8 space-y-6"
                >
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <div className="space-y-1.5">
                      <Label htmlFor="firstName">First Name</Label>
                      <Input id="firstName" name="firstName" placeholder="Jane" required className="rounded-lg" />
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="lastName">Last Name</Label>
                      <Input id="lastName" name="lastName" placeholder="Smith" required className="rounded-lg" />
                    </div>
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="email">Email Address</Label>
                    <Input id="email" name="email" type="email" placeholder="jane@example.com" required className="rounded-lg" />
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="phone">Phone Number</Label>
                    <Input id="phone" name="phone" type="tel" placeholder="(555) 000-0000" className="rounded-lg" />
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="service">Service Needed</Label>
                    <select
                      id="service"
                      name="service"
                      className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm ring-offset-background focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
                    >
                      <option value="">Select a service...</option>
                      <option value="regular">Regular Cleaning</option>
                      <option value="deep">Deep Clean</option>
                      <option value="moveinout">Move-In / Move-Out</option>
                      <option value="other">Not sure yet</option>
                    </select>
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="message">Additional Details</Label>
                    <Textarea
                      id="message"
                      name="message"
                      placeholder="Tell us about your home — size, any special requests, preferred schedule..."
                      rows={4}
                      className="rounded-lg resize-none"
                    />
                  </div>

                  <Button
                    type="submit"
                    disabled={loading}
                    className="w-full bg-primary hover:bg-primary/90 text-primary-foreground rounded-full py-6 text-base font-semibold transition-all duration-200 hover:shadow-md"
                  >
                    {loading ? 'Sending...' : 'Send My Request'}
                  </Button>

                  <p className="text-xs text-gray-400 text-center">
